import {predict,validate} from './inference.mjs';
const $=(s)=>document.querySelector(s);
const pct=(x,d=1)=>(x*100).toFixed(d)+'%';
const num=x=>Number(x).toLocaleString('en-US');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const colors=['#087c86','#6c9bb7','#466487','#ba925e','#94a7b5'];
let R,A,M,currentModel,comparisonModel,profile,capacityPercent=20,view='overview',dirty=false;
const defaultProfile={HighBP:0,HighChol:0,CholCheck:1,BMI:26,Smoker:0,Stroke:0,HeartDiseaseorAttack:0,PhysActivity:1,Fruits:1,Veggies:1,HvyAlcoholConsump:0,AnyHealthcare:1,NoDocbcCost:0,GenHlth:2,MentHlth:2,PhysHlth:0,DiffWalk:0,Sex:1,Age:6,Education:5,Income:6};
const examples=[{name:'Example A · active adult',values:{...defaultProfile,Age:3,BMI:24,GenHlth:1,MentHlth:0}},
 {name:'Example B · mixed indicators',values:{...defaultProfile,Age:8,BMI:29,HighBP:1,GenHlth:3,PhysHlth:3}},
 {name:'Example C · several indicators',values:{...defaultProfile,Age:10,BMI:35,HighBP:1,HighChol:1,GenHlth:4,PhysActivity:0,DiffWalk:1,PhysHlth:12,Smoker:1}}];
const labels={Age:['18–24','25–29','30–34','35–39','40–44','45–49','50–54','55–59','60–64','65–69','70–74','75–79','80+'],GenHlth:['Excellent','Very good','Good','Fair','Poor'],Education:['Never attended / kindergarten','Grades 1–8','Grades 9–11','High school graduate','Some college / technical school','College graduate'],Income:['Under $10,000','$10,000–14,999','$15,000–19,999','$20,000–24,999','$25,000–34,999','$35,000–49,999','$50,000–74,999','$75,000+'],Sex:['Female (source code 0)','Male (source code 1)']};
function modelByName(name){return M.find(m=>m.name===name)}
function resultByName(name){return R.models.find(m=>m.name===name)}
function featureLabel(key){return A.data_dictionary.find(f=>f.key===key)?.label||key}
function heading(kicker,title,subtitle,action=''){return `<div class="heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p class="lead no-margin">${subtitle}</p></div>${action}</div>`}
function stat(label,value,sub){return `<div class="stat"><span class="label">${label}</span><strong>${value}</strong><small>${sub}</small></div>`}
function options(names,value){return names.map(n=>`<option ${n===value?'selected':''}>${esc(n)}</option>`).join('')}
function chart(series,{xLabel='Recall',yLabel='Precision',diagonal=false,baseline=null,theme=false}={}){
  const w=470,h=240,L=43,T=15,W=407,H=183;
  let out=`<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(yLabel)} versus ${esc(xLabel)} chart"><title>${esc(yLabel)} versus ${esc(xLabel)}</title>`;
  [0,.25,.5,.75,1].forEach(v=>{const yy=T+H*(1-v),xx=L+W*v;out+=`<line x1="${L}" x2="${L+W}" y1="${yy}" y2="${yy}" class="grid"/><text x="${L-8}" y="${yy+3}" text-anchor="end">${v.toFixed(2)}</text><text x="${xx}" y="${T+H+17}" text-anchor="middle">${v.toFixed(2)}</text>`;});
  if(diagonal)out+=`<path d="M${L},${T+H} L${L+W},${T}" fill="none" stroke="#a8b0a1" stroke-dasharray="4 4"/>`;
  if(baseline!==null)out+=`<line x1="${L}" x2="${L+W}" y1="${T+H*(1-baseline)}" y2="${T+H*(1-baseline)}" stroke="#a8b0a1" stroke-dasharray="4 4"/>`;
  series.forEach((s,i)=>{const d=s.points.map(([x,y],j)=>`${j?'L':'M'}${(L+W*x).toFixed(2)},${(T+H*(1-y)).toFixed(2)}`).join(' ');out+=`<path d="${d}" fill="none" stroke="${s.color||colors[i]}" stroke-width="2.5"/>`;});
  out+=`<text x="${L+W/2}" y="${h-5}" text-anchor="middle">${xLabel}</text><text x="10" y="10">${yLabel}</text></svg>`;return out;
}
function bars(items,max=1){return items.map(i=>`<div class="barrow ${i.winner?'winner':''}"><span>${esc(i.label)}</span><div class="bartrack"><div class="barfill" style="width:${Math.max(0,i.value/max*100)}%"></div></div><b>${i.text||i.value.toFixed(3)}</b></div>`).join('')}
function heroPlot(){return `<div class="hero-visual"><div class="eyebrow">GET STARTED</div><ol class="user-path"><li><span class="path-number">1</span><div><b>Enter a profile</b>Use a fictional example or complete the questionnaire.</div></li><li><span class="path-number">2</span><div><b>Review the model output</b>See the estimated survey label and what changes the score.</div></li><li><span class="path-number">3</span><div><b>Check the evidence</b>Compare accuracy, missed positives, and false alarms.</div></li></ol><div class="access-note">No registration. No saved health profiles.</div></div>`}
function overview(){const win=resultByName(R.winner),lr=resultByName('Logistic regression'),sh=resultByName('Short-form logistic');return `<section class="welcome"><div class="welcome-copy"><div class="eyebrow">DIABETES INDICATOR RESEARCH</div><h1>Better questions.<br>Clearer understanding.</h1><p>Explore the relationship between everyday health information and reported diabetes status.</p><p class="welcome-small">A student-built research tool. Try a profile, compare the models, and see the evidence behind every result.</p><a class="button" href="#explorer">Explore a health profile <span>→</span></a><a class="welcome-link" href="#data">How the research works →</a></div><figure class="welcome-photo"><img src="assets/health-research.jpg" alt="Healthcare professional using a phone, wearing a stethoscope" width="1600" height="1067"><figcaption>Understanding health data, together.</figcaption></figure></section>
 <div class="research-notice"><b>For research and learning</b><span>This tool estimates a survey label. It does not diagnose diabetes or replace medical care.</span></div>
 <section class="action-strip" aria-label="Explore GlucoScope"><a href="#explorer"><span class="action-icon">01</span><div><b>Try a questionnaire</b><span>Explore a fictional health profile</span></div><span>→</span></a><a href="#compare"><span class="action-icon">02</span><div><b>See the evidence</b><span>Compare performance and mistakes</span></div><span>→</span></a><a href="#learn"><span class="action-icon">03</span><div><b>Understand the research</b><span>Learn the methods, step by step</span></div><span>→</span></a></section>
 <div class="section-title"><div class="eyebrow">BEHIND THE RESEARCH</div><h2>Real data. Results you can inspect.</h2><p>Diabetes indicator research using public survey responses and a separate, held-out test set.</p></div>`+
 `<div class="stats">${stat('Survey responses',num(A.rows),'21 features · one binary target')}${stat('Untouched test records',num(R.test_n),'Matching profiles stay in one split')}${stat('Selected model · ROC-AUC',win.test.auc.toFixed(3),R.winner+' · selected on validation')}${stat('Shorter input set',pct(R.question_reduction,0)+' fewer','8 inputs instead of 21')}</div>`+
 `<div class="grid2"><section class="panel"><div class="panel-head"><div><h2>Models, side by side</h2><p class="sub">Test average precision · higher is better</p></div><span class="tag">Real evaluation</span></div>${bars(R.models.slice(0,4).map(m=>({label:m.name,value:m.test.ap,winner:m.name===R.winner})),.5)}<div class="note">${R.winner} was selected on <b>validation</b> average precision. A different model can score slightly higher on the final test; we do not switch the winner afterward.</div><div class="spacer"><a class="textlink" href="#compare">Inspect metrics & mistakes →</a></div></section>
 <section class="panel"><div class="panel-head"><div><h2>Follow the investigation</h2><p class="sub">Every result has a traceable method.</p></div></div><div class="step"><span class="stepnum">01</span><div><h3>Understand the source</h3><p>${num(A.rows)} survey records. Positive labels represent reported prediabetes or diabetes.</p></div></div><div class="step"><span class="stepnum">02</span><div><h3>Train, calibrate, select, test</h3><p>Four separate data roles prevent the final test from guiding model choices.</p></div></div><div class="step"><span class="stepnum">03</span><div><h3>Measure the trade-offs</h3><p>Precision, recall, calibration, subgroup differences, and a shorter questionnaire.</p></div></div><div class="spacer"><a class="textlink" href="#data">Open the methodology →</a></div></section></div>
 <section class="panel"><div class="panel-head"><div><h2>Less input. How much performance remains?</h2><p class="sub">Prespecified 8-feature logistic model versus the full 21-feature logistic model.</p></div><span class="tag">Questionnaire experiment</span></div><div class="stats no-margin">${stat('Inputs removed','13 of 21','Question count, not measured completion time')}${stat('Average precision retained',pct(sh.test.ap/lr.test.ap),'Relative to full logistic regression')}${stat('Full / short average precision',lr.test.ap.toFixed(3)+' / '+sh.test.ap.toFixed(3),'Both evaluated on the same test records')}${stat('Short-form recall',pct(sh.test.recall),'At its validation-selected F1 threshold')}</div></section>
 <div class="notice"><b>Know the boundary</b><span>This predicts an existing survey label, not future disease or a clinical diagnosis. Historical, self-reported data cannot establish that the model detects undiagnosed diabetes or improves health outcomes.</span></div>`}
function field(f){let content;const blank=profile[f.key]===''||profile[f.key]===undefined;const placeholder=`<option value="" ${blank?'selected':''} disabled>Select an answer</option>`;const chosen=v=>!blank&&Number(profile[f.key])===v?'selected':'';
 if(labels[f.key])content=`<select id="f-${f.key}" name="${f.key}" required>${placeholder}${labels[f.key].map((l,i)=>`<option value="${i+f.min}" ${chosen(i+f.min)}>${l}</option>`).join('')}</select>`;
 else if(f.max===1)content=`<select id="f-${f.key}" name="${f.key}" required>${placeholder}<option value="0" ${chosen(0)}>No</option><option value="1" ${chosen(1)}>Yes</option></select>`;
 else content=`<input id="f-${f.key}" name="${f.key}" type="number" min="${f.min}" max="${f.max}" step="1" value="${blank?'':profile[f.key]}" required>`;
 return `<div class="field"><label for="f-${f.key}">${f.label}</label>${content}<small>${f.description}</small></div>`}
function intakeFields(mod){const groups=[['About the profile',['Age','Sex','BMI']],['Health history',['HighBP','HighChol','CholCheck','Stroke','HeartDiseaseorAttack','DiffWalk']],['Daily habits',['Smoker','PhysActivity','Fruits','Veggies','HvyAlcoholConsump']],['Health and access to care',['GenHlth','MentHlth','PhysHlth','AnyHealthcare','NoDocbcCost','Education','Income']]];return groups.map(([title,keys])=>{const fs=keys.filter(k=>mod.features.includes(k)).map(k=>A.data_dictionary.find(f=>f.key===k));return fs.length?`<fieldset class="intake-group"><legend>${title} <span>${fs.length} questions</span></legend><div class="fields">${fs.map(field).join('')}</div></fieldset>`:''}).join('')}
function pendingResult(incomplete=false){$('#profile-result').innerHTML=`<div class="result-card empty-result"><span class="eyebrow">MODEL OUTPUT</span><h2>${incomplete?'Complete the questionnaire':'Answers changed'}</h2><p>${incomplete?'Choose an answer for every required question, then select Run the model. You can also load a fictional example.':'Select Run the model to calculate an updated result. The previous score is hidden so it cannot be confused with these answers.'}</p></div>`}
function explorer(){const mod=modelByName(currentModel);return heading('HEALTH PROFILE QUESTIONNAIRE','Enter health information','Try fictional examples or enter survey-coded inputs. Nothing you enter is sent to a server or saved.')+
 `<div class="controls"><label for="explorer-model">Model</label><select id="explorer-model">${options(M.map(m=>m.name),currentModel)}</select><span class="tag">${mod.features.length} inputs</span><span class="privacy-label">No login required · answers are not saved</span></div>
 <div class="explorer-layout"><section class="panel"><div class="panel-head"><div><h2>Questionnaire</h2><p class="sub">Start a new profile or load a fictional example. Answer every question before running the model.</p></div></div><div class="intake-intro"><strong>Where do I put my information?</strong>Use the fields below. This tool does not request your name, email, or contact details.</div><div class="chiprow"><button class="chip new-profile" id="new-profile">Start a new profile</button>${examples.map((p,i)=>`<button class="chip" data-example="${i}">${p.name}</button>`).join('')}</div><div class="completion"><div><label for="profile-progress">Questionnaire progress</label><span id="progress-label"></span></div><progress id="profile-progress" value="0" max="21"></progress></div><form id="profile-form">${intakeFields(mod)}<div id="form-errors" role="alert"></div><div class="form-actions"><button class="primary" type="submit">Run the model →</button><span>Educational output. Not a medical assessment.</span></div></form></section>
 <aside><div id="profile-result" aria-live="polite"></div><section class="panel"><h3>What does this number mean?</h3><p class="sub">It is the model's estimated probability of the dataset's positive survey label. It is <b>not a validated personal medical risk</b>, and it does not predict future diabetes.</p><div class="note warn">A low score cannot rule out diabetes. Do not use this experiment to make testing or treatment decisions.</div></section></aside></div>`}
function showPrediction(){const model=modelByName(currentModel),p=predict(model,profile),t=model.threshold;const selected=resultByName(currentModel);const refs=Object.fromEntries(A.data_dictionary.map(f=>{const bins=A.distributions[f.key];let sum=0;return [f.key,bins.find(b=>{sum+=b.n;return sum>=A.rows/2}).value]}));
 const impacts=model.features.filter(k=>Number(profile[k])!==refs[k]).map(k=>({key:k,ref:refs[k],delta:predict(model,{...profile,[k]:refs[k]})-p})).sort((a,b)=>Math.abs(b.delta)-Math.abs(a.delta)).slice(0,5);
 $('#profile-result').innerHTML=`<div class="result-card"><span class="tag">${currentModel}</span><div class="score">${(p*100).toFixed(1)}<small>%</small></div><p>Estimated positive-label probability</p><div class="meter"><span style="width:${p*100}%"></span></div><p>Model classification: <b>${p>=t?'Positive label':'Negative label'}</b><br>Validation-selected threshold: ${pct(t)}. This is a research operating point.</p></div><section class="panel"><h3>What changes this output?</h3><p class="sub">One-at-a-time replacement with the dataset median. Values below show change in score, in percentage points.</p>${impacts.map(i=>`<div class="sensitivity"><div><span>${featureLabel(i.key)} → code ${i.ref}</span><b>${i.delta>=0?'+':''}${(i.delta*100).toFixed(1)} pp</b></div><div class="bartrack"><div class="barfill" style="width:${Math.min(100,Math.abs(i.delta)*400)}%;background:${i.delta<0?'#73aeba':'#bd9b72'}"></div></div></div>`).join('')||'<p class="sub">This profile matches the reference values.</p>'}<div class="note">Sensitivity describes the model, not causation. Changing a behavior does not guarantee this change in a person's health.</div><button class="secondary spacer" id="export-profile">Download this result</button></section>`;
 $('#export-profile').onclick=()=>download('glucoscope-profile-result.json',JSON.stringify({model:currentModel,inputs:profile,probability:p,threshold:t,classification:p>=t?1:0,notice:'Educational survey-label estimate; not a diagnosis or future risk forecast.'},null,2),'application/json');
}
function compare(){const m=resultByName(comparisonModel),cm=m.test.confusion;return heading('MEASURE PERFORMANCE, NOT JUST ACCURACY','Show the evidence.','All final metrics use the same held-out test set. Model choice and classification thresholds were fixed on development data.')+
 `<section class="panel"><div class="panel-head"><div><h2>Final model comparison</h2><p class="sub">${num(R.test_n)} test records · ${num(R.test_positive)} positives · thresholds maximize validation F1</p></div><a class="textlink" href="assets/metrics.csv" download>Download CSV ↓</a></div><div class="tablewrap"><table><thead><tr><th>Model</th><th>Accuracy</th><th>Precision</th><th>Recall</th><th>F1</th><th>Avg. precision</th><th>ROC-AUC</th><th>Brier ↓</th></tr></thead><tbody>${R.models.map(r=>`<tr class="${r.name===R.winner?'selected':''}"><td><b>${r.name}</b>${r.name===R.winner?'<small>Selected on validation</small>':''}</td>${['accuracy','precision','recall','f1','ap','auc','brier'].map(k=>`<td>${r.test[k].toFixed(3)}</td>`).join('')}</tr>`).join('')}<tr><td>Always-negative baseline<small>Constant training prevalence score</small></td>${['accuracy','precision','recall','f1','ap','auc','brier'].map(k=>`<td>${R.dummy[k].toFixed(3)}</td>`).join('')}</tr></tbody></table></div><div class="note">The baseline gets ${pct(R.dummy.accuracy)} accuracy by predicting every record negative, yet catches zero positive labels. That is why accuracy is not our selection metric.</div></section>
 <div class="controls"><label for="comparison-model">Inspect model</label><select id="comparison-model">${options(R.models.map(m=>m.name),comparisonModel)}</select></div><div class="grid2"><section class="panel"><h2>Precision–recall</h2><p class="sub">Precision: how many flags are correct? Recall: how many positives are caught?</p>${chart([{points:m.pr_curve}],{baseline:R.test_positive/R.test_n})}<div class="legend"><span><i class="dot"></i>${m.name}</span><span>– – Positive prevalence</span></div></section><section class="panel"><h2>The mistakes, made visible</h2><p class="sub">Threshold ${pct(m.test.threshold)} · rows actual, columns predicted</p><div class="matrix"><div class="cell"><strong>${num(cm[0][0])}</strong>True negatives · correctly negative</div><div class="cell error"><strong>${num(cm[0][1])}</strong>False positives · false alarms</div><div class="cell error"><strong>${num(cm[1][0])}</strong>False negatives · missed positives</div><div class="cell"><strong>${num(cm[1][1])}</strong>True positives · correctly positive</div></div><div class="note">These are survey-label errors. They are not counts of clinically diagnosed or newly detected patients.</div></section>
 <section class="panel"><h2>Probability calibration</h2><p class="sub">A calibrated score should follow the diagonal. Ten equal-frequency bins.</p>${chart([{points:m.calibration_curve}],{xLabel:'Mean predicted probability',yLabel:'Observed positive fraction',diagonal:true})}<p class="sub">Brier: ${m.uncalibrated_brier.toFixed(4)} before → ${m.test.brier.toFixed(4)} after sigmoid calibration. Calibration can help or hurt on new data.</p></section>
 <section class="panel"><h2>Which inputs matter?</h2><p class="sub">Drop in average precision when a feature is shuffled. Sample of 1,200 test records, three repetitions.</p>${bars([...m.importance].sort((a,b)=>b.mean-a.mean).slice(0,6).map(i=>({label:featureLabel(i.feature),value:Math.max(0,i.mean),text:i.mean.toFixed(3)})),Math.max(...m.importance.map(i=>i.mean),.001))}<p class="sub">Correlated features share information. Importance does not establish a cause.</p></section></div>
 <section class="panel"><h2>Does performance vary across groups?</h2><p class="sub">Descriptive audit using the same global threshold. These comparisons do not establish fairness or subgroup clinical validity.</p><div class="tablewrap"><table><thead><tr><th>Group</th><th>Records</th><th>Positive labels</th><th>Recall</th><th>False-positive rate</th><th>Avg. precision</th><th>Brier</th></tr></thead><tbody>${m.subgroups.map(g=>`<tr><td>${g.group==='Sex'?(g.label==='0'?'Recorded female':'Recorded male'):'Age '+g.label}</td><td>${num(g.n)}</td><td>${num(g.positive)}</td><td>${pct(g.recall)}</td><td>${pct(g.fpr)}</td><td>${g.ap.toFixed(3)}</td><td>${g.brier.toFixed(3)}</td></tr>`).join('')}</tbody></table></div><div class="note">Selected-model recall 95% cluster-bootstrap interval: ${R.uncertainty.winner_recall_ci.map(v=>pct(v)).join('–')}. Average-precision difference versus logistic regression: ${R.uncertainty.ap_difference_vs_logistic_ci.map(v=>v.toFixed(4)).join(' to ')}. These intervals reflect test-sample variation, not uncertainty for a person's score.</div></section>`}
function capacityPage(){return heading('A RETROSPECTIVE RESOURCE-ALLOCATION EXPERIMENT','What if capacity is limited?','Rank the held-out cohort by model score, then select only a fixed fraction. This simulation counts known survey labels; it does not validate clinical outreach.')+
 `<div class="grid2"><section class="panel"><div class="eyebrow">SELECTION CAPACITY</div><div class="capacity-value"><span id="capacity-number">${capacityPercent}</span><small>% of the test cohort</small></div><label class="sub" for="capacity-range">Choose the fraction of profiles to select</label><input id="capacity-range" type="range" min="5" max="100" step="5" value="${capacityPercent}"><div class="legend" style="justify-content:space-between"><span>5% · limited capacity</span><span>100% · everyone</span></div><div class="note">Each strategy gets the exact same number of selections. A score tie is resolved by stable row order, not the true label.</div></section><section class="panel"><h2>What are we measuring?</h2><div class="step"><span class="stepnum">1</span><div><h3>Score and rank</h3><p>Sort unseen test profiles by estimated positive-label probability.</p></div></div><div class="step"><span class="stepnum">2</span><div><h3>Select within capacity</h3><p>Take the highest-scored profiles without looking at their answers.</p></div></div><div class="step"><span class="stepnum">3</span><div><h3>Reveal and count</h3><p>Compare selected positives with random-selection expectation and logistic regression.</p></div></div></section></div><section class="panel" id="capacity-results"></section><div class="notice">No claim of reduced disease, medical costs, or improved patient outcomes is supported by this simulation.</div>`}
function showCapacity(){const rows=R.models.map(m=>({name:m.name,...m.capacity.find(c=>c.capacity===capacityPercent/100)})),n=rows[0].selected,expected=n*R.test_positive/R.test_n,w=rows.find(r=>r.name===R.winner),lr=rows.find(r=>r.name==='Logistic regression');$('#capacity-number').textContent=capacityPercent;$('#capacity-results').innerHTML=`<div class="panel-head"><div><h2>${num(n)} selections. Compare the yield.</h2><p class="sub">${num(R.test_positive)} total positive labels in ${num(R.test_n)} test records.</p></div><span class="tag">Same capacity for everyone</span></div><div class="tablewrap"><table><thead><tr><th>Strategy</th><th>Selected</th><th>Positive labels captured</th><th>Recall</th><th>Precision</th></tr></thead><tbody>${rows.map(r=>`<tr class="${r.name===R.winner?'selected':''}"><td>${r.name}</td><td>${num(r.selected)}</td><td>${num(r.captured)}</td><td>${pct(r.recall)}</td><td>${pct(r.precision)}</td></tr>`).join('')}<tr><td>Random selection · expected</td><td>${num(n)}</td><td>${expected.toFixed(1)}</td><td>${pct(n/R.test_n)}</td><td>${pct(R.test_positive/R.test_n)}</td></tr></tbody></table></div><div class="note">At this capacity, ${R.winner} captures <b>${pct((w.captured-lr.captured)/lr.captured)} ${w.captured>=lr.captured?'more':'relative change in'} positive labels</b> versus logistic regression (${num(w.captured)} versus ${num(lr.captured)}), and ${(w.captured/expected).toFixed(2)}× the random-selection expectation. This is a retrospective result, not a clinical outcome.</div>`}
function dataPage(){return heading('THE DATA AND THE DECISIONS','Nothing hidden in the pipeline.','A traceable source, explicit preprocessing, and an evaluation designed to keep identical input profiles out of different splits.')+
 `<div class="stats">${stat('Records',num(A.rows),'Public UCI export, dataset 891')}${stat('Positive labels',pct(A.prevalence),num(A.positive)+' of '+num(A.rows))}${stat('Missing values','0','Verified in downloaded file')}${stat('Repeated input rows',num(A.duplicate_feature_rows),'Preserved; grouped during splitting')}</div>
 <div class="grid2"><section class="panel"><h2>Four roles. One untouched test.</h2><div class="splitbar">${Object.entries(A.splits).map(([k,v],i)=>`<div style="width:${100*v.n/A.rows}%;background:${colors[i]}">${Math.round(100*v.n/A.rows)}%</div>`).join('')}</div><div class="tablewrap"><table><thead><tr><th>Role</th><th>Records</th><th>Purpose</th></tr></thead><tbody>${Object.entries(A.splits).map(([k,v])=>`<tr><td>${k}</td><td>${num(v.n)}</td><td>${{train:'3-fold group CV and model fitting',calibration:'Fit sigmoid calibration only',validation:'Choose model and F1 thresholds',test:'Final frozen evaluation'}[k]}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><h2>What we actually changed</h2><ul class="bullet-list"><li>Removed ID from the predictors. The target is never an input.</li><li>Validated integer codes and permitted ranges. No missing-value imputation was necessary.</li><li>Kept unusual BMI values; did not assume a rare observation was an error.</li><li>Retained identical profiles because different respondents can give the same answers.</li><li>Grouped by all 21 inputs before splitting; ${num(A.conflicting_profiles)} profiles have conflicting outcome labels.</li><li>Scaled logistic inputs inside each training fold. Trees used original codes.</li><li>Retained class imbalance. Used average precision and validation-selected thresholds; no synthetic oversampling.</li></ul></section></div>
 <section class="panel"><div class="panel-head"><div><h2>Explore a feature</h2><p class="sub">Descriptive whole-dataset summaries. Associations are not causes.</p></div><select id="data-feature" aria-label="Feature to explore">${A.data_dictionary.map(f=>`<option value="${f.key}" ${f.key==='Age'?'selected':''}>${f.label}</option>`).join('')}</select></div><div id="feature-distribution"></div></section>
 <section class="panel"><h2>Data dictionary</h2><p class="sub">All predictors are integer-coded; several represent ordered categories rather than exact quantities.</p><div class="tablewrap"><table><thead><tr><th>Feature</th><th>Values</th><th>Meaning</th></tr></thead><tbody>${A.data_dictionary.map(f=>`<tr><td><b>${f.key}</b></td><td>${f.min}–${f.max}</td><td>${f.description}</td></tr>`).join('')}</tbody></table></div></section>
 <section class="panel"><h2>Limitations are part of the result</h2><ul class="bullet-list"><li>UCI metadata contains inconsistent prose about the source year, feature count, and labels. This project pins the actual 253,680-row, 21-feature binary export and uses its target definition. See the report for provenance caveats.</li><li>Self-reported existing status is not verified disease detection, future incidence, or treatment response.</li><li>Survey weights, collection dates, and respondent identifiers suitable for longitudinal linkage are not available in this processed export. Results are sample-level, not population prevalence estimates.</li><li>No independent clinical cohort or prospective study has been used. Public deployment does not imply clinical validation.</li><li>Ordinal encoding assumes an order; logistic regression also imposes a linear effect per code step. This is a modeling limitation.</li></ul><p class="sub">Source SHA-256: <code style="overflow-wrap:anywhere">${A.source_sha256}</code></p></section>`}
function showDistribution(key='Age'){const bins=A.distributions[key],max=Math.max(...bins.map(b=>b.n));$('#feature-distribution').innerHTML=`<div class="tablewrap"><table><thead><tr><th>Value / category</th><th>Records</th><th>Frequency</th><th>Positive-label rate</th></tr></thead><tbody>${bins.map(b=>`<tr><td>${labels[key]?.[b.value-A.data_dictionary.find(f=>f.key===key).min]||b.value}</td><td>${num(b.n)}</td><td style="width:35%"><div class="bartrack"><div class="barfill" style="width:${100*b.n/max}%"></div></div></td><td>${pct(b.positive_rate)}</td></tr>`).join('')}</tbody></table></div>`}
const lessons=[
 ['01','The question and the dataset','We predict a known survey label from 21 other answers. Each row is an observation, each input column a feature, and the hidden answer the target. A positive target combines prediabetes or diabetes under the UCI definition. This is supervised binary classification.','Explain why this dataset cannot tell us who develops diabetes five years later.'],
 ['02','Why a training score is not enough','A model can memorize examples. We fit on about 60%, calibrate on 10%, choose the model and threshold on 10%, and evaluate once on 20%. Matching input profiles stay together. Three-fold cross-validation inside training chooses hyperparameters.','Why must the scaler learn its mean from training data only?'],
 ['03','Logistic regression: a weighted score','First standardize each feature: z = (x − training mean) / training standard deviation. Compute s = intercept + Σ(weight × z). Convert the score to a probability using sigmoid(s) = 1 / (1 + exp(−s)). Training minimizes log loss plus regularization. A separate fitted sigmoid calibrates the score.','If the raw score is zero, what does the uncalibrated sigmoid return? Answer: 0.5.'],
 ['04','Trees, forests, and boosting','A tree asks successive questions such as “BMI ≤ 29.5?” and ends at a leaf. A random forest averages many trees trained with randomization. Gradient boosting adds shallow trees sequentially to improve an objective; ours uses logistic loss. Both are ensembles, but their training processes differ.','Why can a forest be less unstable than one deep tree?'],
 ['05','The confusion matrix and its math','Precision = TP/(TP+FP). Recall = TP/(TP+FN). Accuracy = (TP+TN)/N. F1 = 2×precision×recall/(precision+recall). With 40 correct flags, 60 false alarms, and 10 missed positives: precision = 40%, recall = 80%, F1 ≈ 53.3%.','Which metric directly tells us what fraction of positive labels we missed? Use 1 − recall.'],
 ['06','Ranking, calibration, and thresholds','Average precision summarizes precision as recall increases across score cutoffs; higher is better. Brier score = mean((probability − label)²); lower is better. Calibration checks whether scores agree with observed frequencies. Our classification thresholds maximize F1 on validation data, not the test set.','Why is 0.5 not necessarily the best threshold for an imbalanced dataset?'],
 ['07','The short questionnaire experiment','We chose eight features before final testing and compared a short logistic model against full logistic regression. Input reduction = (21−8)/21 = 61.9%. Retained AP = short AP / full AP. This measures question count and model performance—not the time people actually take.','Why should we compare the short model with the full version of the same algorithm?'],
 ['08','Explanations, uncertainty, and limits','Permutation importance shuffles one feature and measures performance loss. The profile explorer changes one input at a time to a reference value. Neither proves causation. Bootstrap intervals describe uncertainty across resampled test profiles; they are not personal medical confidence intervals.','Could the model associate alcohol with a lower score without alcohol preventing disease? Explain confounding.'],
 ['09','From Python to a live website','Python trains models and exports their exact parameters. JavaScript applies the same scaling, tree rules, and sigmoid calibration. Tests compare 500 Python and browser-engine predictions. The site fetches public model artifacts; profile inputs stay in browser memory.','Explain why this site can make real predictions without sending a profile to an API.'],
 ['10','Present the results honestly','Start with the question, show the dataset and split, compare models, demonstrate one profile, explain errors, run the capacity simulation, and finish with limitations. The selected model is the validation winner, even if another model later scores slightly better on the test.','State one supported numeric improvement and one claim the project cannot support.'],
];
function learn(){return heading('UNDERSTAND IT. REPRODUCE IT. PRESENT IT.','Learn one piece at a time.','A ten-part route from the problem to the math, code, and presentation. Each chunk ends with a question you should be able to explain to a teammate.')+
 `<section class="panel"><div class="downloadgrid"><a class="download" href="downloads/product-testing-checklist.md" download><strong>Product testing checklist ↗</strong><span>Step-by-step actions and expected results</span></a><a class="download" href="downloads/glucoscope-source.zip" download><strong>Complete source code ↗</strong><span>Training, website, tests, report, and guides</span></a><a class="download" href="downloads/research-report.md" download><strong>Research report ↗</strong><span>Methods, actual results, limitations</span></a><a class="download" href="downloads/teaching-guide.md" download><strong>Teaching & presentation guide ↗</strong><span>Math, worked examples, demo checklist</span></a></div></section>
 ${lessons.map(([n,t,b,q])=>`<details><summary><span class="badge-number">${n}</span> &nbsp; ${t}</summary><div><p>${b}</p><div class="note"><b>Check your understanding:</b> ${q}</div></div></details>`).join('')}
 <section class="panel spacer"><h2>Reproduce the investigation</h2><p class="sub">Python 3.11+ and Node.js. The source includes pinned dependencies and a dataset checksum.</p><pre><code>python -m venv .venv
source .venv/bin/activate
pip install -r requirements.txt
python src/train.py
node tests/parity.mjs
python src/build_docs.py
python -m http.server 8000 --directory dist</code></pre><p class="sub">Training downloads the public UCI dataset if absent. Model fitting is a local batch process; the deployed site never retrains on visitors' input.</p></section>
 <div class="notice">The complete source download includes the training pipeline, executed notebook, measured results, verification tests, and deployment-ready website.</div>`}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function updateProgress(){const inputs=[...document.querySelectorAll('#profile-form [name]')];const count=inputs.filter(e=>e.value!==''&&e.checkValidity()).length;$('#profile-progress').max=inputs.length;$('#profile-progress').value=count;$('#progress-label').textContent=`${count} of ${inputs.length} answered`}
function bind(){if(view==='explorer'){updateProgress();$('#new-profile').onclick=()=>{profile=Object.fromEntries(A.data_dictionary.map(f=>[f.key,'']));dirty=false;render()};$('#profile-form').oninput=e=>{if(e.target.name){profile[e.target.name]=e.target.value;updateProgress();dirty=true;pendingResult(validate(profile,A.data_dictionary,modelByName(currentModel).features).length>0)}};$('#explorer-model').onchange=e=>{currentModel=e.target.value;render()};document.querySelectorAll('[data-example]').forEach(b=>b.onclick=()=>{profile={...examples[Number(b.dataset.example)].values};dirty=false;render()});$('#profile-form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));const candidate={...profile,...data};const errors=validate(candidate,A.data_dictionary,modelByName(currentModel).features);$('#form-errors').innerHTML=errors.length?`<div class="errorbox spacer">${errors.map(esc).join('<br>')}</div>`:'';if(!errors.length){profile=Object.fromEntries(Object.entries(candidate).map(([k,v])=>[k,Number(v)]));dirty=false;showPrediction()}};if(validate(profile,A.data_dictionary,modelByName(currentModel).features).length)pendingResult(true);else if(dirty)pendingResult();else showPrediction()}if(view==='compare')$('#comparison-model').onchange=e=>{comparisonModel=e.target.value;render()};if(view==='capacity'){$('#capacity-range').oninput=e=>{capacityPercent=Number(e.target.value);showCapacity()};showCapacity()}if(view==='data'){$('#data-feature').onchange=e=>showDistribution(e.target.value);showDistribution()}}
function render(){view=location.hash.slice(1)||'overview';const pages={overview,explorer,compare,capacity:capacityPage,data:dataPage,learn};if(!pages[view])view='overview';document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.dataset.page===view);if(a.dataset.page===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('#breadcrumb').textContent={overview:'Overview',explorer:'Profile explorer',compare:'Model evidence',capacity:'Capacity simulator',data:'Dataset & methods',learn:'Learn & reproduce'}[view];$('#main').innerHTML=pages[view]();document.body.dataset.view=view;$('#main-nav').classList.remove('is-open');$('#menu-toggle').setAttribute('aria-expanded','false');bind()}
$('#menu-toggle').onclick=()=>{const open=$('#main-nav').classList.toggle('is-open');$('#menu-toggle').setAttribute('aria-expanded',String(open))};
try{[R,A,M]=await Promise.all(['results','audit','models'].map(async n=>{const r=await fetch(`assets/${n}.json`);if(!r.ok)throw Error(`Could not load ${n}`);return r.json()}));currentModel=R.winner;comparisonModel=R.winner;profile=Object.fromEntries(A.data_dictionary.map(f=>[f.key,'']));render();window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)})}catch(e){$('#main').innerHTML=`<div class="errorbox"><h2>Could not load research artifacts</h2><p>${esc(e.message)}</p><p>Please refresh. To run locally, serve the dist folder over HTTP.</p></div>`}
